mapper.insert:
INSERT INTO vm_secrets (
    id, vm_id, secret_hash, salt, status, expires_at, last_used_at, rotated_at, created_at
) VALUES (
    #{id}, #{vmId}, #{secretHash}, #{salt}, #{status}, #{expiresAt}, #{lastUsedAt}, #{rotatedAt}, #{createdAt}
)

mapper.select:
SELECT id, vm_id, secret_hash, salt, status, expires_at, last_used_at, rotated_at, created_at
FROM vm_secrets
WHERE id = #{id}

mapper.update:
UPDATE vm_secrets
SET status = #{status}
WHERE id = #{id}

UPDATE vm_secrets
SET last_used_at = NOW()
WHERE id = #{id}
